std::string json_escape(const std::string& value) {
  std::string escaped;
  escaped.reserve(value.size());
  for (const char c : value) {
    switch (c) {
      case '"':
        escaped += "\\\"";
        break;
      case '\\':
        escaped += "\\\\";
        break;
      case '\n':
        escaped += "\\n";
        break;
      case '\r':
        escaped += "\\r";
        break;
      case '\t':
        escaped += "\\t";
        break;
      default:
        escaped += c;
        break;
    }
  }
  return escaped;
}

void append_json_comma(std::ostream& out, bool& first) {
  if (!first) {
    out << ',';
  }
  first = false;
}

void append_json_string(
    std::ostream& out,
    const char* key,
    const std::string& value,
    bool& first) {
  append_json_comma(out, first);
  out << '"' << key << "\":\"" << json_escape(value) << '"';
}

void append_json_u64(
    std::ostream& out,
    const char* key,
    const uint64_t value,
    bool& first) {
  append_json_comma(out, first);
  out << '"' << key << "\":" << value;
}

void append_json_bool(
    std::ostream& out,
    const char* key,
    const bool value,
    bool& first) {
  append_json_comma(out, first);
  out << '"' << key << "\":" << (value ? "true" : "false");
}

std::map<std::string, std::string> parse_space_separated_fields(
    const std::string& row) {
  std::map<std::string, std::string> fields;
  std::istringstream stream(row);
  std::string token;
  while (stream >> token) {
    const size_t equals = token.find('=');
    if (equals == std::string::npos || equals == 0u) {
      continue;
    }
    fields[token.substr(0, equals)] = token.substr(equals + 1u);
  }
  return fields;
}

uint64_t parsed_u64(
    const std::map<std::string, std::string>& fields,
    const char* key) {
  const auto it = fields.find(key);
  if (it == fields.end()) {
    return 0u;
  }
  try {
    return static_cast<uint64_t>(std::stoull(it->second));
  } catch (...) {
    return 0u;
  }
}

uint64_t parsed_u64_or(const std::string& value, const uint64_t fallback) {
  try {
    return static_cast<uint64_t>(std::stoull(value));
  } catch (...) {
    return fallback;
  }
}

int64_t parsed_i64_or(const std::string& value, const int64_t fallback) {
  try {
    return static_cast<int64_t>(std::stoll(value));
  } catch (...) {
    return fallback;
  }
}

void append_json_fields_object(
    std::ostream& out,
    const std::map<std::string, std::string>& fields) {
  bool first = true;
  out << '{';
  for (const auto& field : fields) {
    append_json_string(out, field.first.c_str(), field.second, first);
  }
  out << '}';
}

void append_json_string_array(
    std::ostream& out,
    const char* key,
    const std::vector<std::string>& values,
    bool& first) {
  append_json_comma(out, first);
  out << '"' << key << "\":[";
  for (size_t i = 0; i < values.size(); ++i) {
    if (i > 0) {
      out << ',';
    }
    out << '"' << json_escape(values[i]) << '"';
  }
  out << ']';
}

std::vector<std::string> missing_dependency_metadata_fields(
    const std::map<std::string, std::string>& fields) {
  std::vector<std::string> missing;
  const auto has_true = [&fields](const char* key) {
    const auto it = fields.find(key);
    return it != fields.end() && it->second == "1";
  };
  if (!has_true("allocation_has_generation")) {
    missing.emplace_back("allocation_generation");
  }
  if (!has_true("allocation_has_byte_range")) {
    missing.emplace_back("byte_range");
  }
  if (!has_true("formal_last_use_proof")) {
    missing.emplace_back("formal_last_use_proof");
  }
  if (!has_true("producer_dispatch_observed")) {
    missing.emplace_back("producer_dispatch");
  }
  if (!has_true("consumer_dispatch_observed")) {
    missing.emplace_back("consumer_dispatch");
  }
  if (!has_true("descriptor_binding_known")) {
    missing.emplace_back("descriptor_binding");
  }
  return missing;
}

std::string field_or(
    const std::map<std::string, std::string>& fields,
    const char* key,
    const char* fallback) {
  const auto it = fields.find(key);
  return it == fields.end() ? std::string(fallback) : it->second;
}

StackRegionOptimizationEligibilitySummary
stack_region_boundary_optimization_eligibility_summary_locked(
    const std::string& selected_boundary_id) {
  StackRegionOptimizationEligibilitySummary summary;
  std::set<std::string> eligible_boundary_ids;
  for (const auto& item : stack_region_boundary_optimization_plan_rows()) {
    const auto fields = parse_space_separated_fields(item.first);
    if (field_or(fields, "selected_boundary_id", "none") !=
        selected_boundary_id) {
      continue;
    }
    summary.candidate_records += std::max<uint64_t>(item.second.count, 1u);
    if (
        field_or(fields, "submit_elision_eligible", "0") != "1" ||
        parsed_u64(fields, "barriers_inserted") == 0u) {
      continue;
    }
    eligible_boundary_ids.insert(
        field_or(fields, "selected_boundary_id", "none"));
    summary.eligible_records += std::max<uint64_t>(item.second.count, 1u);
    summary.barrier_validated_count += item.second.barrier_validated_count;
    summary.barrier_validated_bytes += item.second.bytes;
  }
  summary.eligible_boundary_count = eligible_boundary_ids.size();
  return summary;
}

StackRegionSubmitElisionProofGuardSummary
stack_region_submit_elision_phase_contract_guard_summary_locked(
    const std::string& selected_boundary_id,
    const StackRegionOptimizationEligibilitySummary& eligibility_summary) {
  StackRegionSubmitElisionProofGuardSummary summary;
  summary.descriptor_update_generation_rows =
      stack_descriptor_set_update_generation_rows().size();
  summary.barrier_validated_records =
      eligibility_summary.barrier_validated_count;
  if (eligibility_summary.eligible_boundary_count != 1u) {
    summary.status = "phase_contract_guard_rejected_boundary_count";
    summary.reason = "selected_boundary_count_not_exactly_one";
    return summary;
  }
  if (eligibility_summary.eligible_records == 0u) {
    summary.status = "phase_contract_guard_rejected_no_eligible_plan";
    summary.reason = eligibility_summary.barrier_validated_count == 0u
        ? "actual_norm1_input_barrier_record_missing"
        : "submit_elision_optimization_plan_not_eligible";
    return summary;
  }
  if (summary.descriptor_update_generation_rows == 0u) {
    summary.status = "phase_contract_guard_rejected_descriptor_generation";
    summary.reason = "actual_vk_descriptor_set_update_generation_missing";
    return summary;
  }
  for (const auto& item : stack_region_boundary_submit_plan_rows()) {
    const auto fields = parse_space_separated_fields(item.first);
    if (field_or(fields, "live_boundary_id", "none") !=
        selected_boundary_id) {
      continue;
    }
    const uint64_t count = std::max<uint64_t>(item.second.count, 1u);
    summary.selected_submit_rows += count;
    const bool pending_range_complete =
        field_or(
            fields,
            "pending_dispatch_range_completeness_status",
            "missing") ==
            "pending_dispatch_range_complete_side_effect_rows_match" &&
        field_or(fields, "pending_dispatch_position_range_complete", "0") ==
            "1";
    const bool same_active_command_buffer =
        field_or(
            fields,
            "pending_dispatch_command_buffer_identity_status",
            "missing") == "same_active_command_buffer_recording_scope_observed";
    const bool phase_submit_epoch_crossing =
        field_or(
            fields,
            "pending_dispatch_submit_epoch_transition_status",
            "missing") == "phase_submit_epoch_crossing_observed";
    const bool descriptor_generation_observed =
        summary.descriptor_update_generation_rows > 0u;
    const bool actual_norm1_input_barrier_matched =
        eligibility_summary.barrier_validated_count > 0u;
    const uint64_t pending_resource_count =
        parsed_u64(fields, "pending_resource_count");
    const uint64_t safe_candidate_count =
        parsed_u64(fields, "safe_candidate_count");
    const uint64_t capture_sensitive_count =
        parsed_u64(fields, "capture_sensitive_stack_activation_count");
    const bool old_carry_retire_only_proven =
        pending_resource_count > 0u &&
        safe_candidate_count + capture_sensitive_count >=
            pending_resource_count &&
        capture_sensitive_count <= 1u;
    const bool unknown_ordering_retire_entries_zero =
        old_carry_retire_only_proven;
    const bool no_public_final_host_readback_blocker =
        parsed_u64(fields, "host_visible_or_requested_output_count") == 0u &&
        field_or(fields, "public_scope_rejected", "0") == "0";
    if (pending_range_complete) {
      summary.pending_range_complete_rows += count;
    }
    if (same_active_command_buffer) {
      summary.same_active_command_buffer_rows += count;
    }
    if (descriptor_generation_observed) {
      summary.descriptor_update_generation_rows_for_selected += count;
    }
    if (actual_norm1_input_barrier_matched) {
      summary.actual_norm1_input_barrier_rows += count;
    }
    if (old_carry_retire_only_proven) {
      summary.old_carry_retire_only_rows += count;
    }
    if (unknown_ordering_retire_entries_zero) {
      summary.unknown_ordering_retire_entries_zero_rows += count;
    }
    if (no_public_final_host_readback_blocker) {
      summary.no_public_final_host_readback_blocker_rows += count;
    }
    if (
        pending_range_complete && same_active_command_buffer &&
        phase_submit_epoch_crossing && descriptor_generation_observed &&
        actual_norm1_input_barrier_matched && old_carry_retire_only_proven &&
        unknown_ordering_retire_entries_zero &&
        no_public_final_host_readback_blocker) {
      summary.proof_ready_rows += count;
    }
  }
  if (summary.selected_submit_rows == 0u) {
    summary.status = "phase_contract_guard_missing_live_submit_row";
    summary.reason = "selected_boundary_live_submit_row_not_recorded_yet";
    return summary;
  }
  if (summary.proof_ready_rows == 0u) {
    summary.status = "phase_contract_guard_rejected_predicate_failed";
    summary.reason = "selected_boundary_phase_contract_predicate_failed";
    return summary;
  }
  summary.status = "phase_contract_guard_proof_ready";
  summary.reason = "all_selected_boundary_phase_contract_predicates_satisfied";
  return summary;
}

const char* stack_region_live_submit_eligibility_status(
    const bool live_boundary_matches_selected,
    const StackRegionOptimizationEligibilitySummary& summary) {
  if (!live_boundary_matches_selected) {
    return "live_boundary_not_selected";
  }
  if (summary.candidate_records == 0u) {
    return "live_boundary_identity_matched_eligibility_missing";
  }
  if (summary.eligible_records == 0u) {
    return summary.barrier_validated_count == 0u
        ? "live_boundary_identity_matched_barrier_validation_missing"
        : "live_boundary_identity_matched_eligibility_missing";
  }
  if (summary.eligible_boundary_count != 1u) {
    return "rejected_broad_match";
  }
  return "live_boundary_eligible_but_behavior_disabled";
}

bool boundary_has_planned_non_capture_norm1_consumer(
    const std::map<std::string, std::string>& fields) {
  return field_or(fields, "consumer_dispatch_planned", "0") == "1" &&
      field_or(fields, "consumer_dispatch_proof", "missing") ==
      "planned_non_capture_residual2_to_norm1";
}

bool dependency_is_requested_capture_edge(
    const std::map<std::string, std::string>& fields) {
  return field_or(fields, "consumer_phase", "unknown") ==
          "intermediate_capture" &&
      field_or(fields, "consumer_descriptor_role", "unknown") ==
          "requested_intermediate_output";
}

std::string stack_output_device_consumer_registration_key(
    const std::string& captured_block,
    const std::string& output_role) {
  return "capture_block=" + captured_block + ":output_role=" + output_role;
}

std::string stack_output_device_consumer_registration_key(
    const std::map<std::string, std::string>& fields) {
  return stack_output_device_consumer_registration_key(
      field_or(fields, "captured_block", "unknown"),
      field_or(fields, "output_role", "unknown"));
}

VulkanVisionStackPhase vision_stack_phase_from_graph_name(
    const std::string& name) {
  if (name == "stack_entry") {
    return VulkanVisionStackPhase::StackEntry;
  }
  if (name == "block_entry") {
    return VulkanVisionStackPhase::BlockEntry;
  }
  if (name == "norm1") {
    return VulkanVisionStackPhase::Norm1;
  }
  if (name == "qkv_linear") {
    return VulkanVisionStackPhase::QkvLinear;
  }
  if (name == "qkv_transform") {
    return VulkanVisionStackPhase::QkvTransform;
  }
  if (name == "attention") {
    return VulkanVisionStackPhase::Attention;
  }
  if (name == "proj_linear") {
    return VulkanVisionStackPhase::ProjLinear;
  }
  if (name == "residual1") {
    return VulkanVisionStackPhase::Residual1;
  }
  if (name == "norm2") {
    return VulkanVisionStackPhase::Norm2;
  }
  if (name == "fc1_gelu") {
    return VulkanVisionStackPhase::Fc1Gelu;
  }
  if (name == "fc2") {
    return VulkanVisionStackPhase::Fc2;
  }
  if (name == "residual2") {
    return VulkanVisionStackPhase::Residual2;
  }
  if (name == "intermediate_capture") {
    return VulkanVisionStackPhase::IntermediateCapture;
  }
  if (name == "stack_exit") {
    return VulkanVisionStackPhase::StackExit;
  }
  return VulkanVisionStackPhase::Unknown;
}

