void append_stack_region_boundary_optimization_plan_json(
    std::ostream& out,
    const std::vector<std::string>& rows,
    bool& first) {
  uint64_t candidate_records = 0u;
  uint64_t non_capture_records = 0u;
  uint64_t live_buffer_bound_records = 0u;
  uint64_t stage_access_available_records = 0u;
  uint64_t insertion_point_available_records = 0u;
  uint64_t barrier_validated_records = 0u;
  uint64_t behavior_change_allowed_records = 0u;
  uint64_t submit_elision_eligible_records = 0u;
  uint64_t barriers_inserted = 0u;
  uint64_t submits_removed = 0u;
  std::map<std::string, uint64_t> status_counts;
  std::map<std::string, uint64_t> fail_closed_counts;
  for (const auto& row : rows) {
    const auto fields = parse_space_separated_fields(row);
    const uint64_t count = std::max<uint64_t>(parsed_u64(fields, "count"), 1u);
    candidate_records += count;
    if (field_or(fields, "non_capture_boundary", "0") == "1") {
      non_capture_records += count;
    }
    live_buffer_bound_records +=
        parsed_u64(fields, "live_buffer_bound_count");
    stage_access_available_records +=
        parsed_u64(fields, "stage_access_available_count");
    insertion_point_available_records +=
        parsed_u64(fields, "insertion_point_available_count");
    barrier_validated_records += parsed_u64(fields, "barrier_validated_count");
    behavior_change_allowed_records +=
        parsed_u64(fields, "behavior_change_allowed_count");
    submit_elision_eligible_records +=
        parsed_u64(fields, "submit_elision_eligible_count");
    barriers_inserted += parsed_u64(fields, "barriers_inserted");
    submits_removed += parsed_u64(fields, "submits_removed");
    status_counts[field_or(fields, "submit_elision_status", "missing")] +=
        count;
    fail_closed_counts[field_or(fields, "fail_closed_reason", "missing")] +=
        count;
  }

  append_json_comma(out, first);
  out << "\"stack_region_boundary_optimization_plan\":{";
  bool plan_first = true;
  append_json_string(
      out, "schema", "StackRegionBoundaryOptimizationPlan.v0", plan_first);
  append_json_bool(out, "default_behavior_unchanged", true, plan_first);
  append_json_bool(out, "opt_in_only", true, plan_first);
  append_json_string(
      out,
      "submit_elision_env",
      "PYTORCH_VULKAN_STACK_REGION_SUBMIT_ELISION_CANARY",
      plan_first);
  append_json_u64(out, "candidate_records", candidate_records, plan_first);
  append_json_u64(out, "non_capture_records", non_capture_records, plan_first);
  append_json_u64(
      out, "live_buffer_bound_records", live_buffer_bound_records, plan_first);
  append_json_u64(
      out,
      "stage_access_available_records",
      stage_access_available_records,
      plan_first);
  append_json_u64(
      out,
      "insertion_point_available_records",
      insertion_point_available_records,
      plan_first);
  append_json_u64(
      out, "barrier_validated_records", barrier_validated_records, plan_first);
  append_json_u64(
      out,
      "behavior_change_allowed_records",
      behavior_change_allowed_records,
      plan_first);
  append_json_u64(
      out,
      "submit_elision_eligible_records",
      submit_elision_eligible_records,
      plan_first);
  append_json_u64(out, "barriers_inserted", barriers_inserted, plan_first);
  append_json_u64(out, "submits_removed", submits_removed, plan_first);
  append_json_u64(
      out,
      "submits_removed_outside_selected_boundary",
      0u,
      plan_first);
  append_json_comma(out, plan_first);
  out << "\"status_counts\":";
  append_u64_map_object(out, status_counts);
  append_json_comma(out, plan_first);
  out << "\"fail_closed_reason_counts\":";
  append_u64_map_object(out, fail_closed_counts);
  append_json_comma(out, plan_first);
  out << "\"records\":[";
  for (size_t i = 0; i < rows.size(); ++i) {
    if (i > 0) {
      out << ',';
    }
    append_stack_region_boundary_optimization_plan_record(out, rows[i], i);
  }
  out << "]}";
}

struct StackRegionExitSubmitRuntimePointSummary final {
  bool observed = false;
  uint64_t count = 0u;
  uint64_t had_cmd_count = 0u;
  uint64_t command_buffer_recording_id = 0u;
  uint64_t submit_epoch_before = 0u;
  uint64_t submit_epoch_after = 0u;
  uint64_t timeline_value = 0u;
  uint64_t pending_dispatch_count = 0u;
  uint64_t region_exit_close_submit_owner_lifecycle_id = 0u;
  uint32_t region_exit_close_submit_owner_lifecycle_state = 0u;
  bool region_exit_close_submit_owner_behavior_enabled = false;
  bool region_exit_close_submit_owner_authorizes_submit_elision = false;
  bool close_submit_owner_handoff_available = false;
};

StackRegionExitSubmitRuntimePointSummary
summarize_stack_region_exit_submit_runtime_points(
    const std::vector<std::string>& rows,
    const bool planned_region_context_present,
    const VulkanStackPlannedRegionContext& planned_region_context) {
  StackRegionExitSubmitRuntimePointSummary summary;
  for (const auto& row : rows) {
    const auto fields = parse_space_separated_fields(row);
    bool row_matches_context = false;
    if (planned_region_context_present) {
      const std::string expected_stack_region_id =
          stack_region_row_token(planned_region_context.region_id);
      const std::string expected_stack_context_id =
          stack_region_row_token(planned_region_context.stack_context_id);
      const std::string expected_bridge_session_id =
          stack_region_row_token(planned_region_context.bridge_session_id);
      const std::string expected_stack_plan_id =
          stack_region_row_token(planned_region_context.stack_plan_id);
      row_matches_context =
          field_or(fields, "context_present", "0") == "1" &&
          field_or(fields, "stack_region_id", "missing") ==
              expected_stack_region_id &&
          field_or(fields, "stack_context_id", "missing") ==
              expected_stack_context_id &&
          field_or(fields, "bridge_session_id", "missing") ==
              expected_bridge_session_id &&
          field_or(fields, "stack_plan_id", "missing") ==
              expected_stack_plan_id;
    } else {
      row_matches_context =
          rows.size() == 1u &&
          field_or(fields, "submit_origin", "missing") ==
              "StackPlannedRecordingSubmit";
    }
    if (!row_matches_context) {
      continue;
    }
    summary.count += parsed_u64(fields, "count");
    summary.had_cmd_count += parsed_u64(fields, "had_cmd_count");
    summary.command_buffer_recording_id =
        parsed_u64(fields, "command_buffer_recording_id");
    summary.submit_epoch_before = parsed_u64(fields, "submit_epoch_before");
    summary.submit_epoch_after = parsed_u64(fields, "submit_epoch_after");
    summary.timeline_value = parsed_u64(fields, "timeline_value");
    summary.pending_dispatch_count =
        parsed_u64(fields, "pending_dispatch_count");
    summary.region_exit_close_submit_owner_lifecycle_id =
        parsed_u64(fields, "region_exit_close_submit_owner_lifecycle_id");
    summary.region_exit_close_submit_owner_lifecycle_state = static_cast<uint32_t>(
        parsed_u64(fields, "region_exit_close_submit_owner_lifecycle_state"));
    summary.region_exit_close_submit_owner_behavior_enabled =
        field_or(fields, "region_exit_close_submit_owner_behavior_enabled", "0") ==
        "1";
    summary.region_exit_close_submit_owner_authorizes_submit_elision =
        field_or(
            fields,
            "region_exit_close_submit_owner_authorizes_submit_elision",
            "0") == "1";
    summary.close_submit_owner_handoff_available =
        field_or(fields, "close_submit_owner_handoff_available", "0") == "1";
  }
  if (
      summary.count == 0u && !planned_region_context_present &&
      rows.size() == 1u) {
    const auto fields = parse_space_separated_fields(rows.front());
    if (
        field_or(fields, "submit_origin", "missing") ==
        "StackPlannedRecordingSubmit") {
      summary.count += parsed_u64(fields, "count");
      summary.had_cmd_count += parsed_u64(fields, "had_cmd_count");
      summary.command_buffer_recording_id =
          parsed_u64(fields, "command_buffer_recording_id");
      summary.submit_epoch_before = parsed_u64(fields, "submit_epoch_before");
      summary.submit_epoch_after = parsed_u64(fields, "submit_epoch_after");
      summary.timeline_value = parsed_u64(fields, "timeline_value");
      summary.pending_dispatch_count =
          parsed_u64(fields, "pending_dispatch_count");
      summary.region_exit_close_submit_owner_lifecycle_id =
          parsed_u64(fields, "region_exit_close_submit_owner_lifecycle_id");
      summary.region_exit_close_submit_owner_lifecycle_state =
          static_cast<uint32_t>(parsed_u64(
              fields, "region_exit_close_submit_owner_lifecycle_state"));
      summary.region_exit_close_submit_owner_behavior_enabled =
          field_or(
              fields,
              "region_exit_close_submit_owner_behavior_enabled",
              "0") == "1";
      summary.region_exit_close_submit_owner_authorizes_submit_elision =
          field_or(
              fields,
              "region_exit_close_submit_owner_authorizes_submit_elision",
              "0") == "1";
      summary.close_submit_owner_handoff_available =
          field_or(fields, "close_submit_owner_handoff_available", "0") == "1";
    }
  }
  summary.observed = summary.count > 0u && summary.had_cmd_count > 0u;
  return summary;
}

