std::vector<std::string> stack_dispatch_aggregate_snapshot() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  std::vector<std::string> rows;
  rows.reserve(stack_dispatch_aggregate().size());
  for (const auto& item : stack_dispatch_aggregate()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second;
    rows.push_back(row.str());
  }
  return rows;
}

std::vector<std::string> stack_allocation_aggregate_snapshot() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  std::vector<std::string> rows;
  rows.reserve(stack_allocation_aggregate().size());
  for (const auto& item : stack_allocation_aggregate()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " peak_live_estimate_bytes="
        << item.second.peak_live_estimate_bytes;
    rows.push_back(row.str());
  }
  return rows;
}

std::vector<std::string>
stack_output_device_consumer_registration_snapshot() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  std::vector<std::string> rows;
  rows.reserve(stack_output_device_consumer_registrations().size());
  for (const auto& item : stack_output_device_consumer_registrations()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count;
    rows.push_back(row.str());
  }
  return rows;
}

std::vector<std::string> stack_dispatch_dependency_dry_run_snapshot() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  std::vector<std::string> rows;
  rows.reserve(
      stack_dispatch_dependency_dispatch_rows().size() +
      stack_dispatch_dependency_insertion_point_rows().size() +
      stack_dispatch_dependency_live_buffer_binding_rows().size() +
      stack_dispatch_dependency_live_image_binding_rows().size() +
      stack_descriptor_set_update_generation_rows().size() +
      stack_dispatch_dependency_dry_run_rows().size() +
      stack_region_boundary_submit_plan_rows().size() +
      stack_region_barrier_only_canary_rows().size() +
      stack_region_pre_dispatch_proof_table_rows().size() +
      stack_region_boundary_optimization_plan_rows().size() +
      stack_region_submit_elision_canary_rows().size() +
      stack_region_single_recording_canary_rows().size() +
      stack_region_exit_submit_runtime_point_rows().size() +
      stack_raw_resource_producer_registration_rows().size());
  for (const auto& item : stack_dispatch_dependency_dispatch_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " first_position=" << item.second.first_position
        << " last_position=" << item.second.last_position;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_dispatch_dependency_insertion_point_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " next_recorded_dispatch_first_position="
        << item.second.first_position
        << " next_recorded_dispatch_last_position=" << item.second.last_position;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_dispatch_dependency_live_buffer_binding_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " next_recorded_dispatch_first_position="
        << item.second.first_position
        << " next_recorded_dispatch_last_position=" << item.second.last_position;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_dispatch_dependency_live_image_binding_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " next_recorded_dispatch_first_position="
        << item.second.first_position
        << " next_recorded_dispatch_last_position=" << item.second.last_position;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_descriptor_set_update_generation_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " next_recorded_dispatch_first_position="
        << item.second.first_position
        << " next_recorded_dispatch_last_position=" << item.second.last_position
        << " observed_descriptor_update_write_count="
        << item.second.write_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_dispatch_dependency_dry_run_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " queue_submit=" << item.second.queue_submit_count
        << " fully_proven_count=" << item.second.fully_proven_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_boundary_submit_plan_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " queue_submit=" << item.second.queue_submit_count
        << " submit_removed=" << item.second.submit_removed_count
        << " barriers_inserted=" << item.second.barrier_inserted_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_barrier_only_canary_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " pre_dispatch_proof_matched_count="
        << item.second.pre_dispatch_proof_matched_count
        << " live_buffer_bound_count=" << item.second.live_buffer_bound_count
        << " submit_removed=" << item.second.submit_removed_count
        << " barriers_inserted=" << item.second.barrier_inserted_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_pre_dispatch_proof_table_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " proof_complete_count=" << item.second.proof_complete_count
        << " live_buffer_bound_count=" << item.second.live_buffer_bound_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_boundary_optimization_plan_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " bytes=" << item.second.bytes
        << " proof_complete_count=" << item.second.proof_complete_count
        << " live_buffer_bound_count=" << item.second.live_buffer_bound_count
        << " stage_access_available_count="
        << item.second.stage_access_available_count
        << " insertion_point_available_count="
        << item.second.insertion_point_available_count
        << " barrier_validated_count=" << item.second.barrier_validated_count
        << " behavior_change_allowed_count="
        << item.second.behavior_change_allowed_count
        << " submit_elision_eligible_count="
        << item.second.submit_elision_eligible_count
        << " barriers_inserted=" << item.second.barrier_inserted_count
        << " submits_removed=" << item.second.submit_removed_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_submit_elision_canary_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " candidate_records=" << item.second.candidate_records
        << " eligible_records=" << item.second.eligible_records
        << " eligible_boundary_count=" << item.second.eligible_boundary_count
        << " barrier_validated_count=" << item.second.barrier_validated_count
        << " submits_removed=" << item.second.submit_removed_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_single_recording_canary_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " candidate_records=" << item.second.candidate_records
        << " eligible_records=" << item.second.eligible_records
        << " eligible_boundary_count=" << item.second.eligible_boundary_count
        << " barrier_validated_count=" << item.second.barrier_validated_count
        << " proof_ready_records=" << item.second.proof_ready_records
        << " selected_submit_rows=" << item.second.selected_submit_rows
        << " submits_removed=" << item.second.submit_removed_count
        << " submits_removed_outside_selected_boundary="
        << item.second.outside_selected_submit_removed_count;
    rows.push_back(row.str());
  }
  for (const auto& item : stack_region_exit_submit_runtime_point_rows()) {
    const bool close_submit_owner_available =
        stack_region_single_recording_close_submit_owner_available(
            item.second.region_exit_close_submit_owner_lifecycle_id,
            item.second.region_exit_close_submit_owner_lifecycle_state,
            item.second.region_exit_close_submit_owner_behavior_enabled);
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " had_cmd_count=" << item.second.had_cmd_count
        << " no_cmd_count=" << item.second.no_cmd_count
        << " command_buffer_recording_id="
        << item.second.command_buffer_recording_id
        << " submit_epoch_before=" << item.second.submit_epoch_before
        << " submit_epoch_after=" << item.second.submit_epoch_after
        << " timeline_value=" << item.second.timeline_value
        << " pending_dispatch_count=" << item.second.pending_dispatch_count
        << " region_exit_close_submit_owner_lifecycle_id="
        << item.second.region_exit_close_submit_owner_lifecycle_id
        << " region_exit_close_submit_owner_lifecycle_state="
        << item.second.region_exit_close_submit_owner_lifecycle_state
        << " region_exit_close_submit_owner_lifecycle_status="
        << stack_region_single_recording_close_submit_owner_lifecycle_status(
               item.second.region_exit_close_submit_owner_lifecycle_state)
        << " region_exit_close_submit_owner_behavior_enabled="
        << (item.second.region_exit_close_submit_owner_behavior_enabled ? "1"
                                                                        : "0")
        << " region_exit_close_submit_owner_authorizes_submit_elision="
        << (item.second
                    .region_exit_close_submit_owner_authorizes_submit_elision
                ? "1"
                : "0")
        << " close_submit_owner_handoff_available="
        << (close_submit_owner_available ? "1" : "0")
        << " close_submit_owner_handoff_status="
        << (close_submit_owner_available
                ? "region_exit_close_submit_owner_handoff_available_stack_exit_close_submit_owner"
                : stack_region_single_recording_close_submit_owner_blocker(
                      item.second.region_exit_close_submit_owner_lifecycle_id,
                      item.second
                          .region_exit_close_submit_owner_lifecycle_state,
                      item.second
                          .region_exit_close_submit_owner_behavior_enabled))
        << " behavior_neutral=1 default_behavior_unchanged=1"
        << " phase_boundary_submits_preserved=1"
        << " submit_elision_enabled=0"
        << " deferred_submit_enabled=0"
        << " authorizes_submit_elision=0";
    rows.push_back(row.str());
  }
  for (const auto& item : stack_raw_resource_producer_registration_rows()) {
    std::ostringstream row;
    row << item.first << " count=" << item.second.count
        << " observed_byte_range=" << item.second.byte_range
        << " observed_allocated_bytes=" << item.second.allocated_bytes;
    rows.push_back(row.str());
  }
  return rows;
}

void reset_stack_dispatch_aggregate() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  stack_dispatch_aggregate().clear();
}

void reset_stack_allocation_aggregate() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  stack_allocation_aggregate().clear();
}

void reset_stack_dispatch_dependency_dry_run() {
  std::lock_guard<std::mutex> guard(stack_aggregate_mutex());
  stack_dispatch_dependency_dispatch_rows().clear();
  stack_dispatch_dependency_insertion_point_rows().clear();
  stack_dispatch_dependency_live_buffer_binding_rows().clear();
  stack_dispatch_dependency_live_image_binding_rows().clear();
  stack_descriptor_set_update_generation_rows().clear();
  stack_dispatch_dependency_dry_run_rows().clear();
  stack_region_boundary_submit_plan_rows().clear();
  stack_region_barrier_only_canary_rows().clear();
  stack_region_pre_dispatch_proof_table_rows().clear();
  stack_region_boundary_optimization_plan_rows().clear();
  stack_region_submit_elision_canary_rows().clear();
  stack_region_single_recording_canary_rows().clear();
  stack_region_exit_submit_runtime_point_rows().clear();
  stack_raw_resource_producer_registration_rows().clear();
  stack_output_device_consumer_registrations().clear();
}

void note_vulkan_queue_wait_idle() {
  vulkan_sync_counters().queue_wait_idle_count.fetch_add(
      1u, std::memory_order_relaxed);
}

void note_vulkan_forced_sync(VulkanForcedSyncReason reason) {
  VulkanSyncCounters& counters = vulkan_sync_counters();
  counters.forced_sync_count.fetch_add(1u, std::memory_order_relaxed);
  switch (reason) {
    case VulkanForcedSyncReason::ExplicitSynchronize:
      counters.forced_sync_explicit_synchronize_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::TensorCpuReadback:
      counters.forced_sync_tensor_cpu_readback_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::EventSynchronize:
      counters.forced_sync_event_synchronize_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::RetireQueueDrain:
      counters.forced_sync_retire_queue_drain_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::GpuTimestampQueryReset:
      counters.forced_sync_gpu_timestamp_query_reset_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::FallbackPolicyReadback:
      counters.forced_sync_fallback_policy_readback_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
    case VulkanForcedSyncReason::Unknown:
      counters.forced_sync_unknown_count.fetch_add(
          1u, std::memory_order_relaxed);
      return;
  }
}

